INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('Better Theatricals [FR]', '^\b(terminator.?2|alien[^s].*?1979|star.wars.*?(4k|19)(77)|.*?\bempire.strikes.back|.*?\breturn.of.the.jedi|apocalypse.now|the.exorcist.*?1973|donnie.darko|amadeus|payback.*?1999|payback.straight.up.*?2006|almost.famous)\b', NULL, 'Matches movies where the `Theatrical` cut is considered the better version. Subjectively chosen, based on Dictionarry''s personal preferences and major opinion. Needed to override the default special edition preference. Matches:
- Terminator 2: Judgement Day (1991)
- Alien (1979)
- Star Wars OT (1977-1983)
- Apocalypse Now (1979)
- The Exorcist (1973)
- Donnie Darko (2001)
- Amadeus (1984)
- Payback (1999)
- Almost Famous (2000)');
