INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('GZR [FR]', '(?<=^|[\s.-])GZR\b', NULL, 'Matches "GZR" when preceded by whitespace, a hyphen or dot');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('h265 [FR]', '[h][ ._-]?265', NULL, 'A video compression standard that delivers higher efficiency than H.264, enabling better quality at lower bitrates, ideal for 4K and HDR content.');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HANAMi [FR]', '(?<=^|[\s.-])HANAMi\b', NULL, 'Matches "HANAMi" when preceded by whitespace, a hyphen or dot');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HBO Max [FR]', '\b(?:HMAX|HBOM|(?:HBO[ ._-]?MAX)(?=\s*.(?:WEB-?DL|WEBRIP)))\b', NULL, 'HBO Max is an American subscription video-on-demand streaming service that offers a range of original programming and content from WarnerMedia''s vast library, encompassing brands such as Warner Bros., CNN, Cartoon Network, TBS, and Turner Classic Movies. In mid-to-late 2023, HBO Max underwent a rebranding to "Max".');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HD2 [FR]', '(?<=^|[\s.-])HD2\b', NULL, 'Matches "HD2" when preceded by whitespace, a hyphen or dot');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HDForever [FR]', '(?<=^|[\s.-])HDForever\b', NULL, 'Matches "HDForever" when preceded by whitespace, a hyphen or dot');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HDMIDIMADRIDI [FR]', '(?<=^|[\s.-])HDMIDIMADRIDI\b', NULL, 'Matches "HDMIDIMADRIDI" when preceded by whitespace, a hyphen or dot');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HDR [FR]', '\b(HDR(10|(?!\d))|HLG|PQ(10)?)\b', NULL, 'This regex matches a `HDR` generalisation. This can be HDR, HDR10 etc.');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HDR10+ [FR]', '\bHDR10.?(\+|P(lus)?\b)', NULL, 'This regex matches `HDR10` when followed by either a plus sign `+`, `P`, or `Plus`');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HDTV [FR]', '\b(HDTV)\b', NULL, '');
