INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HEVC [FR]', '[xh][ ._-]?265|\bHEVC(\b|\d)', NULL, 'An open source encoder that produces HEVC videos. ');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('HEVCBay [FR]', '(?<=^|[\s.-])HEVCBay\b', NULL, 'Matches "HEVCBay" when preceded by whitespace, a hyphen or dot');
