INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('RiPiT [FR]', '(?<=^|[\s.-])RiPiT\b', NULL, 'Matches "RiPiT" when preceded by whitespace, a hyphen or dot');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('Roku [FR]', '\b(ROKU)\b', NULL, 'The Roku Channel is an over-the-top video streaming service available in the U.S., Canada, Mexico and the U.K. Launched in September 2017. The Roku Channel offers over 400 free live linear TV channels, more than 80,000 free movies and shows, and access to paid content.');
