INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('Paramount+ [EN]', '\b(pmtp|Paramount Plus)\b', NULL, 'Paramount+ is an American subscription video on-demand over-the-top streaming service owned that offers content primarily from the libraries of CBS Media Ventures, CBS Studios, Paramount Media Networks and Paramount Pictures, while also including original series and films, live streaming sports coverage, and in the United States, live streaming of local CBS broadcast stations. ');
INSERT OR IGNORE INTO "regular_expressions" ("name", "pattern", "regex101_id", "description") VALUES ('Parks and Recreation NTb Banned [EN]', '(?i)^parks[ ._-]+and[ ._-]+recreation.*?\b(web[ ._-]?(dl|\.dl))\b.*?-ntb.*', NULL, 'This is to match the show Parks and Recreation and the release group NTb. This is built out because the NTb release of Parks and Rec is a mislabeled WEBRip and causes a download loop.');
